// SafariumRaster — shared C-ABI plumbing (owned by the orchestrator; area agents do not edit this file).
//
// Contract: docs/raster-plan.md. Every exported function is `@_cdecl("sr_...")`, returns Int32
// (0 = ok, < 0 = error; message via sr_last_error) unless documented otherwise.
// Images are passed as six scalars: data, width, height, strideBytes, channels, depth.
// Depth codes follow OpenCV: 0 = u8, 2 = u16, 4 = s32, 5 = f32.

import Foundation

public enum SRDepth: Int32 {
    case u8 = 0
    case u16 = 2
    case s32 = 4
    case f32 = 5

    public var bytes: Int {
        switch self {
        case .u8: return 1
        case .u16: return 2
        case .s32, .f32: return 4
        }
    }
}

public enum SRStatus {
    public static let ok: Int32 = 0
    public static let badArgument: Int32 = -1
    public static let unsupported: Int32 = -2
    public static let ioFailure: Int32 = -3
    public static let internalError: Int32 = -4
}

/// A borrowed view over a caller-owned pixel buffer (numpy array). Never retained past the call.
public struct SRImage {
    public let data: UnsafeMutableRawPointer
    public let width: Int
    public let height: Int
    public let stride: Int      // bytes per row
    public let channels: Int    // 1...4
    public let depth: SRDepth

    public init?(_ data: UnsafeMutableRawPointer?, _ width: Int32, _ height: Int32,
                 _ stride: Int32, _ channels: Int32, _ depth: Int32) {
        guard let data, width >= 0, height >= 0, channels >= 1, channels <= 4,
              let d = SRDepth(rawValue: depth) else { return nil }
        guard Int(stride) >= Int(width) * Int(channels) * d.bytes else { return nil }
        self.data = data
        self.width = Int(width)
        self.height = Int(height)
        self.stride = Int(stride)
        self.channels = Int(channels)
        self.depth = d
    }

    @inline(__always) public func row(_ y: Int) -> UnsafeMutableRawPointer {
        data + y * stride
    }

    public var pixelBytes: Int { channels * depth.bytes }
}

// MARK: - Errors (thread-local last error)

private let errorKey: pthread_key_t = {
    var key = pthread_key_t()
    pthread_key_create(&key) { ptr in
        Unmanaged<NSString>.fromOpaque(ptr).release()
    }
    return key
}()

public func srFail(_ code: Int32, _ message: String) -> Int32 {
    if let old = pthread_getspecific(errorKey) {
        Unmanaged<NSString>.fromOpaque(old).release()
    }
    let s = Unmanaged.passRetained(message as NSString).toOpaque()
    pthread_setspecific(errorKey, s)
    return code
}

/// Copies the calling thread's last error message (UTF-8, NUL-terminated) into buf. Returns its full length.
@_cdecl("sr_last_error")
public func sr_last_error(_ buf: UnsafeMutablePointer<CChar>?, _ cap: Int32) -> Int32 {
    var message = ""
    if let p = pthread_getspecific(errorKey) {
        message = Unmanaged<NSString>.fromOpaque(p).takeUnretainedValue() as String
    }
    let utf8 = Array(message.utf8)
    if let buf, cap > 0 {
        let n = min(utf8.count, Int(cap) - 1)
        for i in 0..<n { buf[i] = CChar(bitPattern: utf8[i]) }
        buf[n] = 0
    }
    return Int32(utf8.count)
}

// MARK: - Threads (SF-VIDEO-1: one worker by default)

nonisolated(unsafe) public var srNumThreads: Int = 1

@_cdecl("sr_set_num_threads")
public func sr_set_num_threads(_ n: Int32) -> Int32 {
    srNumThreads = max(1, Int(n))
    return SRStatus.ok
}

@_cdecl("sr_get_num_threads")
public func sr_get_num_threads() -> Int32 {
    Int32(srNumThreads)
}

/// ABI version so the Python loader can refuse a stale dylib.
@_cdecl("sr_abi_version")
public func sr_abi_version() -> Int32 { 1 }

// MARK: - Helpers shared by areas

@inline(__always) public func srColor(_ p: UnsafePointer<Double>?) -> (Double, Double, Double, Double) {
    guard let p else { return (0, 0, 0, 0) }
    return (p[0], p[1], p[2], p[3])
}

/// Saturating conversions used when writing pixels (match cv2::saturate_cast rounding: round half to even is NOT used; cv2 uses cvRound = nearest, ties to even on most platforms via lrint).
@inline(__always) public func srSatU8(_ v: Double) -> UInt8 {
    let r = v.rounded(.toNearestOrEven)
    return r <= 0 ? 0 : (r >= 255 ? 255 : UInt8(r))
}

@inline(__always) public func srSatU16(_ v: Double) -> UInt16 {
    let r = v.rounded(.toNearestOrEven)
    return r <= 0 ? 0 : (r >= 65535 ? 65535 : UInt16(r))
}
